    {
        usuario: LookUp(
            User,
            ID = varIdUser
        )
    },
    Set(
        varNomeUser,
        usuario.usrNome
    );
    Set(
        varEmailUser,
        usuario.Email
    );
    Set(
        varFuncaoUser,
        usuario.Funcao
    );
