        usuario.Cluster
    );
    Set(
        varAeroUser,
        usuario.Aeroporto
    );
    Set(
        varPerfilUser,
        usuario.Perfil
    );
    Set(
        varAutUser,
        usuario.Autorizacao
    );
    Set(
        varPerfilSafety,
        usuario.View_safety = 1
    )
);
